17	package org.springframework.samples.petclinic.rest.advice;
18	
19	import java.net.URI;
20	import java.time.Instant;
21	import java.util.List;
22	import java.util.Objects;
23	
24	import jakarta.servlet.http.HttpServletRequest;
25	import org.slf4j.Logger;
26	import org.slf4j.LoggerFactory;
27	import org.springframework.dao.DataIntegrityViolationException;
28	import org.springframework.http.HttpStatus;
29	import org.springframework.http.ProblemDetail;
30	import org.springframework.http.ResponseEntity;
31	import org.springframework.samples.petclinic.rest.controller.BindingErrorsResponse;
32	import org.springframework.samples.petclinic.rest.controller.DisposableEmailDomainException;
33	import org.springframework.samples.petclinic.rest.controller.DuplicateOwnerIdentityException;
34	import org.springframework.samples.petclinic.rest.controller.FutureRegistrationDateException;
35	import org.springframework.samples.petclinic.rest.controller.InvalidEmailException;
36	import org.springframework.samples.petclinic.rest.controller.InvalidPostcodeException;
37	import org.springframework.samples.petclinic.rest.controller.InvalidTelephoneException;
38	import org.springframework.samples.petclinic.rest.controller.MissingOwnerFieldsException;
39	import org.springframework.samples.petclinic.rest.controller.OwnerCityCapacityExceededException;
40	import org.springframework.samples.petclinic.rest.controller.OwnerDailyRegistrationLimitExceededException;
41	import org.springframework.samples.petclinic.rest.dto.ValidationMessageDto;
42	import org.springframework.security.access.AccessDeniedException;
43	import org.springframework.validation.BindingResult;
44	import org.springframework.validation.FieldError;
45	import org.springframework.web.bind.MethodArgumentNotValidException;
46	import org.springframework.web.bind.annotation.ControllerAdvice;
47	import org.springframework.web.bind.annotation.ExceptionHandler;
48	import org.springframework.web.bind.annotation.ResponseBody;
49	
50	/**
51	 * Global Exception handler for REST controllers.
52	 * <p>
53	 * This class handles exceptions thrown by REST controllers and returns appropriate HTTP responses to the client.
54	 *
55	 * @author Vitaliy Fedoriv
56	 * @author Alexander Dudkin
57	 */
58	@ControllerAdvice
59	public class ExceptionControllerAdvice {
60	
61	    private static final Logger logger = LoggerFactory.getLogger(ExceptionControllerAdvice.class);
62	    private static final String ERROR_UNEXPECTED = "An unexpected error occurred while processing your request";
63	    private static final String ERROR_DATA_INTEGRITY = "The requested resource could not be processed due to a data constraint violation";
64	    private static final String ERROR_INVALID_REQUEST = "The request contains invalid or missing parameters";
65	
66	    /**
67	     * Private method for constructing the {@link ProblemDetail} object passing the name and details of the exception
68	     * class.
69	     *
70	     * @param e     Object referring to the thrown exception.
71	     * @param status HTTP response status.
72	     * @param url URL request.
73	     */
74	    private ProblemDetail detailBuild(Exception e, HttpStatus status, StringBuffer url, String detail) {
75	        ProblemDetail problemDetail = ProblemDetail.forStatus(status);
76	        problemDetail.setType(URI.create(url.toString()));
77	        problemDetail.setTitle(e.getClass().getSimpleName());
78	        problemDetail.setDetail(detail);
79	        problemDetail.setProperty("timestamp", Instant.now());
80	        problemDetail.setProperty("schemaValidationErrors", List.<ValidationMessageDto>of());
81	        return problemDetail;
82	    }
83	
84	    /**
85	     * Re-throws {@link AccessDeniedException} so Spring Security's {@code ExceptionTranslationFilter}
86	     * translates it as it normally would - 403 for an authenticated user lacking the required role,
87	     * or the configured entry point for an anonymous one. Without this, {@link #handleGeneralException}
88	     * would catch it and report an authorization failure as a 500.
89	     *
90	     * @param e The {@link AccessDeniedException} to propagate
91	     * @throws AccessDeniedException always
92	     */
93	    @ExceptionHandler(AccessDeniedException.class)
94	    public void handleAccessDeniedException(AccessDeniedException e) throws AccessDeniedException {
95	        throw e;
96	    }
97	
98	    /**
99	     * Handles all general exceptions by returning a 500 Internal Server Error status with error details.
100	     *
101	     * @param e The {@link Exception} to be handled
102	     * @param request {@link HttpServletRequest} object referring to the current request.
103	     * @return A {@link ResponseEntity} containing the error information and a 500 Internal Server Error status
104	     */
105	    @ExceptionHandler(Exception.class)
106	    @ResponseBody
107	    public ResponseEntity<ProblemDetail> handleGeneralException(Exception e, HttpServletRequest request) {
108	        logger.error("Unexpected error at {} {}", request.getMethod(), request.getRequestURI(), e);
109	        HttpStatus status = HttpStatus.INTERNAL_SERVER_ERROR;
110	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_UNEXPECTED);
111	        return ResponseEntity.status(status).body(detail);
112	    }
113	
114	    /**
115	     * Handles {@link DataIntegrityViolationException} which typically indicates database constraint violations. This
116	     * method returns a 404 Not Found status if an entity does not exist.
117	     *
118	     * @param e The {@link DataIntegrityViolationException} to be handled
119	     * @param request {@link HttpServletRequest} object referring to the current request.
120	     * @return A {@link ResponseEntity} containing the error information and a 404 Not Found status
121	     */
122	    @ExceptionHandler(DataIntegrityViolationException.class)
123	    @ResponseBody
124	    public ResponseEntity<ProblemDetail> handleDataIntegrityViolationException(DataIntegrityViolationException e, HttpServletRequest request) {
125	        logger.warn("Data integrity violation at {} {}: {}",
126	            request.getMethod(),
127	            request.getRequestURI(),
128	            e.getMessage());
129	        logger.debug("Data integrity violation stacktrace", e);
130	        HttpStatus status = HttpStatus.NOT_FOUND;
131	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
132	        return ResponseEntity.status(status).body(detail);
133	    }
134	
135	    /**
136	     * Handles exception thrown by Bean Validation on controller methods parameters
137	     *
138	     * @param e The {@link MethodArgumentNotValidException} to be handled
139	     * @param request {@link HttpServletRequest} object referring to the current request.
140	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
141	     */
142	    @ExceptionHandler(MethodArgumentNotValidException.class)
143	    @ResponseBody
144	    public ResponseEntity<ProblemDetail> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
145	        HttpStatus status = HttpStatus.BAD_REQUEST;
146	        BindingErrorsResponse errors = new BindingErrorsResponse();
147	        BindingResult bindingResult = e.getBindingResult();
148	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
149	        detail.setProperty("errors", bindingResult.getFieldErrors().stream()
150	            .map(FieldError::getField)
151	            .distinct()
152	            .toList());
153	        if (bindingResult.hasErrors()) {
154	            errors.addAllErrors(bindingResult);
155	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
156	                .map(fieldError -> {
157	                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
158	                    String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
159	                    String message = "Field '%s' %s (rejected value: %s)".formatted(
160	                        fieldError.getField(),
161	                        defaultMessage,
162	                        rejectedValue);
163	                    return new ValidationMessageDto(message)
164	                        .putAdditionalProperty("field", fieldError.getField())
165	                        .putAdditionalProperty("rejectedValue", rejectedValue)
166	                        .putAdditionalProperty("defaultMessage", defaultMessage);
167	                })
168	                .toList();
169	            logger.debug("Validation error at {} {}: {}",
170	                request.getMethod(),
171	                request.getRequestURI(),
172	                bindingResult.getFieldErrors());
173	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
174	            return ResponseEntity.status(status).body(detail);
175	        }
176	        return ResponseEntity.status(status).body(detail);
177	    }
178	
179	    /**
180	     * Handles {@link MissingOwnerFieldsException} raised when an owner request omits or
181	     * leaves blank one or more required fields. Returns a 400 Bad Request whose
182	     * {@code errors} array names each offending field.
183	     *
184	     * @param e The {@link MissingOwnerFieldsException} to be handled
185	     * @param request {@link HttpServletRequest} object referring to the current request.
186	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
187	     */
188	    @ExceptionHandler(MissingOwnerFieldsException.class)
189	    @ResponseBody
190	    public ResponseEntity<ProblemDetail> handleMissingOwnerFieldsException(MissingOwnerFieldsException e, HttpServletRequest request) {
191	        HttpStatus status = HttpStatus.BAD_REQUEST;
192	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
193	        detail.setProperty("errors", e.getMissingFields());
194	        return ResponseEntity.status(status).body(detail);
195	    }
196	
197	    /**
198	     * Handles {@link InvalidTelephoneException} raised when an owner request supplies a
199	     * telephone number that cannot form a valid E.164 number — either the wrong total digit
200	     * count or a national number whose length does not match its country code. Returns a 400
201	     * Bad Request whose {@code errors} array names the {@code telephone} field.
202	     *
203	     * @param e The {@link InvalidTelephoneException} to be handled
204	     * @param request {@link HttpServletRequest} object referring to the current request.
205	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
206	     */
207	    @ExceptionHandler(InvalidTelephoneException.class)
208	    @ResponseBody
209	    public ResponseEntity<ProblemDetail> handleInvalidTelephoneException(InvalidTelephoneException e, HttpServletRequest request) {
210	        HttpStatus status = HttpStatus.BAD_REQUEST;
211	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
212	        detail.setProperty("errors", List.of("telephone"));
213	        return ResponseEntity.status(status).body(detail);
214	    }
215	
216	    /**
217	     * Handles {@link InvalidEmailException} raised when an owner request supplies an email
218	     * address that is not syntactically valid. Returns a 400 Bad Request whose
219	     * {@code errors} array names the {@code email} field.
220	     *
221	     * @param e The {@link InvalidEmailException} to be handled
222	     * @param request {@link HttpServletRequest} object referring to the current request.
223	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
224	     */
225	    @ExceptionHandler(InvalidEmailException.class)
226	    @ResponseBody
227	    public ResponseEntity<ProblemDetail> handleInvalidEmailException(InvalidEmailException e, HttpServletRequest request) {
228	        HttpStatus status = HttpStatus.BAD_REQUEST;
229	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
230	        detail.setProperty("errors", List.of("email"));
231	        return ResponseEntity.status(status).body(detail);
232	    }
233	
234	    /**
235	     * Handles {@link DisposableEmailDomainException} raised when an owner request supplies an
236	     * email address whose domain is on the disposable-domain blocklist. Returns a 400 Bad
237	     * Request whose {@code errors} array names the {@code email} field.
238	     *
239	     * @param e The {@link DisposableEmailDomainException} to be handled
240	     * @param request {@link HttpServletRequest} object referring to the current request.
241	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
242	     */
243	    @ExceptionHandler(DisposableEmailDomainException.class)
244	    @ResponseBody
245	    public ResponseEntity<ProblemDetail> handleDisposableEmailDomainException(DisposableEmailDomainException e, HttpServletRequest request) {
246	        HttpStatus status = HttpStatus.BAD_REQUEST;
247	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
248	        detail.setProperty("errors", List.of("email"));
249	        return ResponseEntity.status(status).body(detail);
250	    }
251	
252	    /**
253	     * Handles {@link InvalidPostcodeException} raised when an owner request supplies a
254	     * {@code postcode} that is not four digits or is out of range for the city's region. Returns
255	     * a 400 Bad Request whose {@code errors} array names the {@code postcode} field.
256	     *
257	     * @param e The {@link InvalidPostcodeException} to be handled
258	     * @param request {@link HttpServletRequest} object referring to the current request.
259	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
260	     */
261	    @ExceptionHandler(InvalidPostcodeException.class)
262	    @ResponseBody
263	    public ResponseEntity<ProblemDetail> handleInvalidPostcodeException(InvalidPostcodeException e, HttpServletRequest request) {
264	        HttpStatus status = HttpStatus.BAD_REQUEST;
265	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
266	        detail.setProperty("errors", List.of("postcode"));
267	        return ResponseEntity.status(status).body(detail);
268	    }
269	
270	    /**
271	     * Handles {@link DuplicateOwnerIdentityException} raised when an owner request would create an
272	     * owner whose whole derived identity key (normalized telephone, email and household id) already
273	     * belongs to an existing owner. This is the single duplicate check: telephone, email and
274	     * household are no longer detected independently but only through the combined key. Returns a
275	     * 409 Conflict whose {@code errors} array names the {@code identityKey} field.
276	     *
277	     * @param e The {@link DuplicateOwnerIdentityException} to be handled
278	     * @param request {@link HttpServletRequest} object referring to the current request.
279	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
280	     */
281	    @ExceptionHandler(DuplicateOwnerIdentityException.class)
282	    @ResponseBody
283	    public ResponseEntity<ProblemDetail> handleDuplicateOwnerIdentityException(DuplicateOwnerIdentityException e, HttpServletRequest request) {
284	        HttpStatus status = HttpStatus.CONFLICT;
285	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
286	        detail.setProperty("errors", List.of("identityKey"));
287	        return ResponseEntity.status(status).body(detail);
288	    }
289	
290	    /**
291	     * Handles {@link OwnerCityCapacityExceededException} raised when an owner request would
292	     * create an owner in a city that already holds the maximum permitted number of owners.
293	     * Returns a 409 Conflict whose {@code errors} array names the {@code city} field.
294	     *
295	     * @param e The {@link OwnerCityCapacityExceededException} to be handled
296	     * @param request {@link HttpServletRequest} object referring to the current request.
297	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
298	     */
299	    @ExceptionHandler(OwnerCityCapacityExceededException.class)
300	    @ResponseBody
301	    public ResponseEntity<ProblemDetail> handleOwnerCityCapacityExceededException(OwnerCityCapacityExceededException e, HttpServletRequest request) {
302	        HttpStatus status = HttpStatus.CONFLICT;
303	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
304	        detail.setProperty("errors", List.of("city"));
305	        return ResponseEntity.status(status).body(detail);
306	    }
307	
308	    /**
309	     * Handles {@link OwnerDailyRegistrationLimitExceededException} raised when an owner request
310	     * would exceed the maximum number of owners permitted to register on a single day (by
311	     * registration date). Returns a 429 Too Many Requests.
312	     *
313	     * @param e The {@link OwnerDailyRegistrationLimitExceededException} to be handled
314	     * @param request {@link HttpServletRequest} object referring to the current request.
315	     * @return A {@link ResponseEntity} containing the error information and a 429 Too Many Requests status.
316	     */
317	    /**
318	     * Handles {@link FutureRegistrationDateException} raised when an owner request supplies a
319	     * {@code registrationDate} later than the current server date. Returns a 400 Bad Request
320	     * whose {@code errors} array names the {@code registrationDate} field.
321	     *
322	     * @param e The {@link FutureRegistrationDateException} to be handled
323	     * @param request {@link HttpServletRequest} object referring to the current request.
324	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
325	     */
326	    @ExceptionHandler(FutureRegistrationDateException.class)
327	    @ResponseBody
328	    public ResponseEntity<ProblemDetail> handleFutureRegistrationDateException(FutureRegistrationDateException e, HttpServletRequest request) {
329	        HttpStatus status = HttpStatus.BAD_REQUEST;
330	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
331	        detail.setProperty("errors", List.of("registrationDate"));
332	        return ResponseEntity.status(status).body(detail);
333	    }
334	
335	    @ExceptionHandler(OwnerDailyRegistrationLimitExceededException.class)
336	    @ResponseBody
337	    public ResponseEntity<ProblemDetail> handleOwnerDailyRegistrationLimitExceededException(OwnerDailyRegistrationLimitExceededException e, HttpServletRequest request) {
338	        HttpStatus status = HttpStatus.TOO_MANY_REQUESTS;
339	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
340	        detail.setProperty("errors", List.of("registrationDate"));
341	        return ResponseEntity.status(status).body(detail);
342	    }
343	
344	}
