66	@RestController
67	@CrossOrigin(exposedHeaders = "errors, content-type")
68	@RequestMapping("/api")
69	public class OwnerRestControllerV1 implements OwnersApi {
70	
71	    private final ClinicService clinicService;
72	
73	    private final OwnerMapper ownerMapper;
74	
75	    private final PetMapper petMapper;
76	
77	    private final VisitMapper visitMapper;
78	
79	    private final OwnerFieldsValidator ownerFieldsValidator;
80	
81	    private final PostcodeValidator postcodeValidator;
82	
83	    private final TelephoneNormalizer telephoneNormalizer;
84	
85	    private final EmailNormalizer emailNormalizer;
86	
87	    private final AddressNormalizer addressNormalizer;
88	
89	    private final BusinessDayResolver businessDayResolver;
90	
91	    private final OwnerAuditLogger ownerAuditLogger;
92	
93	    private final WelcomeNotifier welcomeNotifier;
94	
95	    private final HouseholdIdGenerator householdIdGenerator;
96	
97	    private final IdempotencyKeyRegistry idempotencyKeyRegistry;
98	
99	    /** Maximum number of owners a single city may hold before further creations are rejected. */
100	    static final long MAX_OWNERS_PER_CITY = 50;
101	
102	    /** Number of owners already in a city at or above which a new owner is flagged as approaching the per-city capacity limit. */
103	    static final long CAPACITY_WARNING_THRESHOLD = 40;
104	
105	    /** Maximum number of owners that may be registered on a single day before further creations are rejected. */
106	    static final long MAX_OWNERS_PER_DAY = 100;
107	
108	    /** Number of owners already registered on a day above which a new owner is flagged with a bulk-signup warning. */
109	    static final long BULK_SIGNUP_WARNING_THRESHOLD = 80;
110	
111	    public OwnerRestControllerV1(ClinicService clinicService,
112	                                 OwnerMapper ownerMapper,
113	                                 PetMapper petMapper,
114	                                 VisitMapper visitMapper,
115	                                 OwnerFieldsValidator ownerFieldsValidator,
116	                                 PostcodeValidator postcodeValidator,
117	                                 TelephoneNormalizer telephoneNormalizer,
118	                                 EmailNormalizer emailNormalizer,
119	                                 AddressNormalizer addressNormalizer,
120	                                 BusinessDayResolver businessDayResolver,
121	                                 OwnerAuditLogger ownerAuditLogger,
122	                                 WelcomeNotifier welcomeNotifier,
123	                                 HouseholdIdGenerator householdIdGenerator,
124	                                 IdempotencyKeyRegistry idempotencyKeyRegistry) {
