141	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
142	    @Override
143	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
144	        Collection<Owner> owners;
145	        if (lastName != null) {
146	            owners = this.clinicService.findOwnerByLastName(lastName);
147	        } else {
148	            owners = this.clinicService.findAllOwners();
149	        }
150	        if (owners.isEmpty()) {
151	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
152	        }
153	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
154	    }
155	
156	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
157	    @Override
158	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
159	        Owner owner = this.clinicService.findOwnerById(ownerId);
160	        if (owner == null) {
161	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
162	        }
163	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
164	    }
165	
166	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
167	    @Override
168	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto, String idempotencyKey) {
169	        Integer existingOwnerId = this.idempotencyKeyRegistry.findOwnerId(idempotencyKey);
170	        if (existingOwnerId != null) {
171	            Owner existingOwner = this.clinicService.findOwnerById(existingOwnerId);
172	            if (existingOwner != null) {
173	                return new ResponseEntity<>(ownerMapper.toOwnerDto(existingOwner), HttpStatus.OK);
174	            }
175	        }
176	        this.normalizeAddress(ownerFieldsDto);
177	        this.ownerFieldsValidator.validate(ownerFieldsDto);
178	        this.postcodeValidator.validate(ownerFieldsDto.getPostcode(), ownerFieldsDto.getCity());
179	        HttpHeaders headers = new HttpHeaders();
180	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
181	        owner.setTelephone(this.telephoneNormalizer.normalize(owner.getTelephone()));
182	        owner.setEmail(this.emailNormalizer.normalize(owner.getEmail()));
183	        LocalDate serverDate = LocalDate.now();
184	        if (owner.getRegistrationDate() != null && owner.getRegistrationDate().isAfter(serverDate)) {
185	            throw new FutureRegistrationDateException(owner.getRegistrationDate(), serverDate);
186	        }
187	        LocalDate effectiveDate = owner.getRegistrationDate() != null ? owner.getRegistrationDate() : serverDate;
188	        owner.setRegistrationDate(this.businessDayResolver.toBusinessDay(effectiveDate));
189	        long ownersRegisteredToday = this.clinicService.countOwnersRegisteredOn(owner.getRegistrationDate());
190	        if (ownersRegisteredToday >= MAX_OWNERS_PER_DAY) {
191	            throw new OwnerDailyRegistrationLimitExceededException(owner.getRegistrationDate(), MAX_OWNERS_PER_DAY);
192	        }
193	        owner.setBulkSignupWarning(ownersRegisteredToday > BULK_SIGNUP_WARNING_THRESHOLD);
194	        long ownersInCity = this.clinicService.countOwnersInCity(owner.getCity());
195	        if (ownersInCity >= MAX_OWNERS_PER_CITY) {
196	            throw new OwnerCityCapacityExceededException(owner.getCity(), MAX_OWNERS_PER_CITY);
197	        }
198	        owner.setCapacityWarning(ownersInCity >= CAPACITY_WARNING_THRESHOLD);
199	        if (owner.getPostcode() != null) {
200	            owner.setHouseholdId(this.householdIdGenerator.generate(owner.getLastName(), owner.getPostcode()));
201	        }
202	        if (!this.clinicService.findOwnersByIdentityKey(owner.getIdentityKey()).isEmpty()) {
203	            throw new DuplicateOwnerIdentityException(owner.getIdentityKey());
204	        }
205	        Owner softMatch = this.clinicService.findSoftMatchOf(owner);
206	        if (softMatch != null) {
207	            owner.setPossibleDuplicateOf(softMatch.getId());
208	        }
209	        this.clinicService.saveOwner(owner);
210	        this.idempotencyKeyRegistry.remember(idempotencyKey, owner.getId());
211	        this.ownerAuditLogger.logCreated(owner);
212	        this.welcomeNotifier.enqueueWelcome(owner);
213	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
214	        headers.setLocation(UriComponentsBuilder.newInstance()
215	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
216	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
217	    }
218	
219	    /**
220	     * Canonicalize the request's address fields in place, preferring the structured form. When a
221	     * non-blank {@code addressLine1} is supplied it and the optional {@code addressLine2} are
222	     * normalized and the composed value stored on {@code address}; otherwise only the flat
223	     * {@code address} is normalized. This keeps the stored {@code address} the single canonical
224	     * value everything downstream reads.
225	     */
226	    private void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
227	        if (ownerFieldsDto.getAddressLine1() != null && !ownerFieldsDto.getAddressLine1().isBlank()) {
228	            ownerFieldsDto.setAddressLine1(this.addressNormalizer.normalize(ownerFieldsDto.getAddressLine1()));
229	            String line2 = this.addressNormalizer.normalize(ownerFieldsDto.getAddressLine2());
230	            ownerFieldsDto.setAddressLine2(line2.isEmpty() ? null : line2);
231	            ownerFieldsDto.setAddress(
232	                this.addressNormalizer.compose(ownerFieldsDto.getAddressLine1(), ownerFieldsDto.getAddressLine2()));
233	        }
234	        else {
235	            ownerFieldsDto.setAddress(this.addressNormalizer.normalize(ownerFieldsDto.getAddress()));
236	        }
237	    }
