241	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
242	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
243	        if (currentOwner == null) {
244	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
245	        }
246	        currentOwner.setAddress(ownerFieldsDto.getAddress());
247	        currentOwner.setCity(ownerFieldsDto.getCity());
248	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
249	        currentOwner.setLastName(ownerFieldsDto.getLastName());
250	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
251	        currentOwner.setEmail(this.emailNormalizer.normalize(ownerFieldsDto.getEmail()));
252	        this.clinicService.saveOwner(currentOwner);
253	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
254	    }
255	
256	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
257	    @Transactional
258	    @Override
259	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
260	        Owner owner = this.clinicService.findOwnerById(ownerId);
261	        if (owner == null) {
262	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
263	        }
264	        this.clinicService.deleteOwner(owner);
265	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
266	    }
267	
268	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
269	    @Override
270	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
271	        Owner owner = this.clinicService.findOwnerById(ownerId);
272	        if (owner == null) {
273	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
274	        }
275	        HttpHeaders headers = new HttpHeaders();
276	        Pet pet = petMapper.toPet(petFieldsDto);
277	        owner.setId(ownerId);
278	        pet.setOwner(owner);
279	        pet.getType().setName(null);
280	        this.clinicService.savePet(pet);
281	        PetDto petDto = petMapper.toPetDto(pet);
282	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
283	            .buildAndExpand(pet.getId()).toUri());
284	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
285	    }
286	
287	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
288	    @Override
289	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
290	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
291	        if (currentOwner != null) {
292	            Pet currentPet = this.clinicService.findPetById(petId);
293	            if (currentPet != null) {
294	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
295	                currentPet.setName(petFieldsDto.getName());
296	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
297	                this.clinicService.savePet(currentPet);
298	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
299	            }
300	        }
301	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
302	    }
