304	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
305	    @Override
306	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
307	        HttpHeaders headers = new HttpHeaders();
308	        Visit visit = visitMapper.toVisit(visitFieldsDto);
309	        Pet pet = new Pet();
310	        pet.setId(petId);
311	        visit.setPet(pet);
312	        this.clinicService.saveVisit(visit);
313	        VisitDto visitDto = visitMapper.toVisitDto(visit);
314	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
315	            .buildAndExpand(visit.getId()).toUri());
316	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
317	    }
